import { NextResponse } from "next/server";
import { queryOne, execute } from "@/lib/db";
import { signToken } from "@/lib/auth";

async function getSettings() {
  const row = await queryOne(
    "SELECT google_client_id, google_client_secret, github_client_id, github_client_secret FROM web_settings WHERE id = 1"
  );
  return row as {
    google_client_id: string;
    google_client_secret: string;
    github_client_id: string;
    github_client_secret: string;
  } | null;
}

async function getGoogleUser(code: string) {
  const settings = await getSettings();
  const clientId = settings?.google_client_id || process.env.GOOGLE_CLIENT_ID || "";
  const clientSecret = settings?.google_client_secret || process.env.GOOGLE_CLIENT_SECRET || "";

  const tokenRes = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      code,
      client_id: clientId,
      client_secret: clientSecret,
      redirect_uri: `${process.env.NEXT_PUBLIC_BASE_URL}/api/auth/oauth/google/callback`,
      grant_type: "authorization_code",
    }),
  });

  if (!tokenRes.ok) {
    const err = await tokenRes.text();
    throw new Error(`Google token exchange failed: ${err}`);
  }

  const tokens = await tokenRes.json();
  const userRes = await fetch("https://www.googleapis.com/oauth2/v2/userinfo", {
    headers: { Authorization: `Bearer ${tokens.access_token}` },
  });

  if (!userRes.ok) throw new Error("Failed to fetch Google user info");
  return await userRes.json();
}

async function getGitHubUser(code: string) {
  const settings = await getSettings();
  const clientId = settings?.github_client_id || process.env.GITHUB_CLIENT_ID || "";
  const clientSecret = settings?.github_client_secret || process.env.GITHUB_CLIENT_SECRET || "";

  const tokenRes = await fetch("https://github.com/login/oauth/access_token", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      client_id: clientId,
      client_secret: clientSecret,
      code,
    }),
  });

  if (!tokenRes.ok) {
    const err = await tokenRes.text();
    throw new Error(`GitHub token exchange failed: ${err}`);
  }

  const tokens = await tokenRes.json();
  if (tokens.error) throw new Error(`GitHub OAuth error: ${tokens.error_description || tokens.error}`);

  const userRes = await fetch("https://api.github.com/user", {
    headers: { Authorization: `Bearer ${tokens.access_token}` },
  });

  if (!userRes.ok) throw new Error("Failed to fetch GitHub user info");
  const userData = await userRes.json();

  const emailRes = await fetch("https://api.github.com/user/emails", {
    headers: { Authorization: `Bearer ${tokens.access_token}` },
  });

  if (!emailRes.ok) throw new Error("Failed to fetch GitHub emails");
  const emails = await emailRes.json();

  const primary = emails.find((e: any) => e.primary && e.verified);
  return {
    id: String(userData.id),
    email: primary?.email || userData.email,
    name: userData.name || userData.login,
    avatar_url: userData.avatar_url,
  };
}

const PROVIDER_HANDLERS: Record<string, (code: string) => Promise<{ id: string; email: string; name: string; avatar_url?: string }>> = {
  google: getGoogleUser,
  github: getGitHubUser,
};

export async function GET(
  req: Request,
  { params }: { params: Promise<{ provider: string }> }
) {
  try {
    const { provider } = await params;
    const handler = PROVIDER_HANDLERS[provider];
    if (!handler) {
      return NextResponse.json({ error: "Invalid provider" }, { status: 400 });
    }

    const { searchParams } = new URL(req.url);
    const code = searchParams.get("code");
    const error = searchParams.get("error");

    if (error) {
      return NextResponse.redirect(new URL("/login?error=oauth_denied", req.url));
    }

    if (!code) {
      return NextResponse.redirect(new URL("/login?error=missing_code", req.url));
    }

    const oauthUser = await handler(code);

    if (!oauthUser.email) {
      return NextResponse.redirect(new URL("/login?error=no_email", req.url));
    }

    await execute(`
      ALTER TABLE users ADD COLUMN IF NOT EXISTS oauth_provider VARCHAR(50)
    `);
    await execute(`
      ALTER TABLE users ADD COLUMN IF NOT EXISTS oauth_id VARCHAR(255)
    `);
    await execute(`
      ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_url TEXT
    `);

    const existing = await queryOne(
      "SELECT id, name, email, role, avatar_url FROM users WHERE email = $1",
      [oauthUser.email]
    ) as { id: number; name: string; email: string; role: "admin" | "client"; avatar_url?: string | null } | null;

    let user: { id: number; name: string; email: string; role: "admin" | "client"; avatar_url?: string | null };

    if (existing) {
      const newName = oauthUser.name || existing.name;
      const newAvatar = oauthUser.avatar_url || existing.avatar_url || null;
      await execute(
        "UPDATE users SET oauth_provider = $1, oauth_id = $2, avatar_url = $3, name = $4 WHERE id = $5",
        [provider, oauthUser.id, newAvatar, newName, existing.id]
      );
      user = { ...existing, name: newName, avatar_url: newAvatar };
    } else {
      const placeholderPw = `oauth_${provider}_${Date.now()}`;
      const result = await queryOne(
        `INSERT INTO users (name, email, password, role, oauth_provider, oauth_id, avatar_url)
         VALUES ($1, $2, $3, 'client', $4, $5, $6) RETURNING id`,
        [oauthUser.name || oauthUser.email.split("@")[0], oauthUser.email, placeholderPw, provider, oauthUser.id, oauthUser.avatar_url || null]
      ) as { id: number };
      user = { id: result.id, name: oauthUser.name || oauthUser.email.split("@")[0], email: oauthUser.email, role: "client", avatar_url: oauthUser.avatar_url || null };
    }

    const token = signToken(user);
    const dashboardUrl = new URL(
      user.role === "admin" ? "/dashboard/admin" : "/dashboard/client",
      req.url
    );

    const response = NextResponse.redirect(dashboardUrl);
    response.cookies.set("token", token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      maxAge: 60 * 60 * 24 * 7,
      path: "/",
    });

    return response;
  } catch (err: any) {
    console.error(`[OAUTH CALLBACK ERROR]`, err?.message || err);
    const msg = err?.message?.includes("duplicate") ? "account_exists" : "oauth_failed";
    return NextResponse.redirect(new URL(`/login?error=${msg}`, req.url));
  }
}

import { NextResponse } from "next/server";
import { queryOne, execute } from "@/lib/db";

async function getClientId(provider: string): Promise<string> {
  try {
    await execute(`
      ALTER TABLE web_settings
      ADD COLUMN IF NOT EXISTS google_client_id TEXT DEFAULT '',
      ADD COLUMN IF NOT EXISTS github_client_id TEXT DEFAULT '';
    `);
    const row = await queryOne(
      provider === "google"
        ? "SELECT google_client_id FROM web_settings WHERE id = 1"
        : "SELECT github_client_id FROM web_settings WHERE id = 1"
    ) as any;
    if (row) return row[`${provider}_client_id`] || "";
  } catch {}
  return process.env[`${provider.toUpperCase()}_CLIENT_ID`] || "";
}

export async function GET(
  _req: Request,
  { params }: { params: Promise<{ provider: string }> }
) {
  try {
    const { provider } = await params;
    const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || "";

    const clientId = await getClientId(provider);

    if (!clientId) {
      return NextResponse.redirect(
        `${baseUrl}/login?error=${provider}_not_configured`
      );
    }

    const configs: Record<string, { authUrl: string; params: Record<string, string> }> = {
      google: {
        authUrl: "https://accounts.google.com/o/oauth2/v2/auth",
        params: {
          client_id: clientId,
          redirect_uri: `${baseUrl}/api/auth/oauth/google/callback`,
          response_type: "code",
          scope: "openid email profile",
          access_type: "offline",
          prompt: "consent",
        },
      },
      github: {
        authUrl: "https://github.com/login/oauth/authorize",
        params: {
          client_id: clientId,
          redirect_uri: `${baseUrl}/api/auth/oauth/github/callback`,
          scope: "read:user user:email",
        },
      },
    };

    const config = configs[provider];
    if (!config) {
      return NextResponse.redirect(`${baseUrl}/login?error=oauth_failed`);
    }

    const url = new URL(config.authUrl);
    Object.entries(config.params).forEach(([key, value]) => {
      url.searchParams.set(key, value);
    });

    return NextResponse.redirect(url.toString());
  } catch {
    const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || "";
    return NextResponse.redirect(`${baseUrl}/login?error=oauth_failed`);
  }
}

import { NextResponse } from "next/server";
import { queryOne, execute } from "@/lib/db";
import { getSession, signToken } from "@/lib/auth";
import bcrypt from "bcryptjs";

export async function PATCH(req: Request) {
  const user = await getSession();
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  try {
    const { 
      name, 
      last_name, 
      bio, 
      profile_photo, 
      github_url, 
      linkedin_url, 
      twitter_url,
      email,
      password,
      current_password,
      cups_of_coffee,
      contributions,
      admin_signature_url,
    } = await req.json();

    if (user.role === "admin") {
      if (email && email !== user.email) {
        const existing = await queryOne(
          "SELECT id FROM users WHERE email = $1 AND id != $2",
          [email, user.id]
        );
        if (existing) {
          return NextResponse.json({ error: "Email is already taken" }, { status: 400 });
        }
        await execute("UPDATE users SET email = $1 WHERE id = $2", [email, user.id]);
      }
    }

    if (password) {
      if (!current_password) {
        return NextResponse.json({ error: "Current password is required to set a new password" }, { status: 400 });
      }
      const stored = await queryOne(
        "SELECT password FROM users WHERE id = $1",
        [user.id]
      ) as { password: string } | null;
      if (!stored || !bcrypt.compareSync(current_password, stored.password)) {
        return NextResponse.json({ error: "Current password is incorrect" }, { status: 400 });
      }
      const hash = bcrypt.hashSync(password, 10);
      await execute("UPDATE users SET password = $1 WHERE id = $2", [hash, user.id]);
    }

    await execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS cups_of_coffee VARCHAR(50) DEFAULT '0'");
    await execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS contributions VARCHAR(50) DEFAULT '1k+'");
    await execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS admin_signature_url TEXT");

    await execute(
      "UPDATE users SET name = COALESCE($1, name), last_name = COALESCE($2, last_name), bio = COALESCE($3, bio), profile_photo = COALESCE($4, profile_photo), github_url = COALESCE($5, github_url), linkedin_url = COALESCE($6, linkedin_url), twitter_url = COALESCE($7, twitter_url), cups_of_coffee = COALESCE($8, cups_of_coffee), contributions = COALESCE($9, contributions), admin_signature_url = COALESCE($10, admin_signature_url) WHERE id = $11",
      [
        name ?? null,
        last_name ?? null,
        bio ?? null,
        profile_photo ?? null,
        github_url ?? null,
        linkedin_url ?? null,
        twitter_url ?? null,
        cups_of_coffee ?? null,
        contributions ?? null,
        admin_signature_url ?? null,
        user.id
      ]
    );

    const updated = await queryOne(
      "SELECT id, name, email, role, last_name, profile_photo, bio, github_url, linkedin_url, twitter_url, cups_of_coffee, contributions, admin_signature_url FROM users WHERE id = $1",
      [user.id]
    ) as Record<string, unknown>;

    const newToken = signToken({
      id: updated.id as number,
      name: updated.name as string,
      email: updated.email as string,
      role: updated.role as "admin" | "client",
    });

    const response = NextResponse.json({ user: updated });
    response.cookies.set("token", newToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      path: "/",
      maxAge: 60 * 60 * 24 * 7,
    });

    return response;
  } catch (err) {
    return NextResponse.json({ error: "Something went wrong" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { queryOne, execute } from "@/lib/db";
import nodemailer from "nodemailer";

export async function POST(req: Request) {
  try {
    const { name, email } = await req.json();

    if (!name || !email) {
      return NextResponse.json({ error: "Name and email are required" }, { status: 400 });
    }

    const existing = await queryOne("SELECT id FROM users WHERE email = $1", [email]);
    if (existing) {
      return NextResponse.json({ error: "Email already registered" }, { status: 409 });
    }

    const config = await queryOne("SELECT * FROM email_config WHERE id = 1") as any;
    if (!config || !config.smtp_host || !config.smtp_user || !config.smtp_password) {
      return NextResponse.json(
        { error: "Email service is not configured by the administrator yet." },
        { status: 500 }
      );
    }

    const otpCode = Math.floor(100000 + Math.random() * 900000).toString();

    await execute(`
      INSERT INTO pending_otps (email, code, expires_at)
      VALUES ($1, $2, NOW() + INTERVAL '5 minutes')
      ON CONFLICT (email) DO UPDATE 
      SET code = EXCLUDED.code, expires_at = EXCLUDED.expires_at
    `, [email, otpCode]);

    const transporter = nodemailer.createTransport({
      host: config.smtp_host,
      port: Number(config.smtp_port) || 587,
      secure: Number(config.smtp_port) === 465,
      auth: {
        user: config.smtp_user,
        pass: config.smtp_password,
      },
      tls: {
        rejectUnauthorized: false,
      },
    });

    await transporter.sendMail({
      from: `"${config.sender_name || "Dee Jay"}" <${config.sender_email || "otp@deejay.dev"}>`,
      to: email,
      subject: "Verification Code for Account Registration",
      text: `Hello ${name},\n\nYour verification code is: ${otpCode}.\nIt will expire in 5 minutes.`,
      html: `
        <div style="font-family: sans-serif; max-width: 480px; margin: 0 auto; padding: 24px; border: 1px solid #e4e4e7; border-radius: 16px;">
          <h2 style="font-size: 20px; font-weight: bold; color: #18181b; margin-bottom: 8px;">Verify Your Email</h2>
          <p style="font-size: 14px; color: #71717a; margin-bottom: 24px;">Hello <strong>${name}</strong>, use the verification code below to verify your email and complete your registration.</p>
          <div style="background-color: #f4f4f5; border-radius: 12px; padding: 16px; text-align: center; margin-bottom: 24px;">
            <span style="font-family: monospace; font-size: 32px; font-weight: bold; letter-spacing: 6px; color: #06b6d4;">${otpCode}</span>
          </div>
          <p style="font-size: 12px; color: #a1a1aa; margin-top: 24px; border-top: 1px solid #e4e4e7; padding-top: 16px;">This code will expire in 5 minutes. If you did not sign up for an account, please ignore this email.</p>
        </div>
      `,
    });

    return NextResponse.json({ success: true });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || "Something went wrong" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { queryOne, execute } from "@/lib/db";
import { hashPassword, signToken } from "@/lib/auth";

export async function POST(req: Request) {
  try {
    const { name, email, password, otp } = await req.json();

    if (!name || !email || !password || !otp) {
      return NextResponse.json(
        { error: "All fields, including the verification code, are required." },
        { status: 400 }
      );
    }

    if (password.length < 6) {
      return NextResponse.json(
        { error: "Password must be at least 6 characters" },
        { status: 400 }
      );
    }

    const existing = await queryOne("SELECT id FROM users WHERE email = $1", [email]);
    if (existing) {
      return NextResponse.json(
        { error: "Email already registered" },
        { status: 409 }
      );
    }

    // Verify OTP
    const pending = await queryOne("SELECT code, expires_at FROM pending_otps WHERE email = $1", [email]) as any;
    if (!pending) {
      return NextResponse.json(
        { error: "No verification request found for this email. Please request a new code." },
        { status: 400 }
      );
    }

    const expiredCheck = await queryOne(`
      SELECT 1 FROM pending_otps 
      WHERE email = $1 AND NOW() > expires_at
    `, [email]);

    if (expiredCheck) {
      return NextResponse.json(
        { error: "Verification code has expired. Please request a new one." },
        { status: 400 }
      );
    }

    if (pending.code !== otp.trim()) {
      return NextResponse.json(
        { error: "Invalid verification code." },
        { status: 400 }
      );
    }

    // Create user
    const hashed = hashPassword(password);
    const result = await queryOne(
      "INSERT INTO users (name, email, password, role) VALUES ($1, $2, $3, 'client') RETURNING id",
      [name, email, hashed]
    ) as { id: number };

    // Clean up verification
    await execute("DELETE FROM pending_otps WHERE email = $1", [email]);

    const user = {
      id: result.id,
      name,
      email,
      role: "client" as const,
    };

    const token = signToken(user);

    const response = NextResponse.json({ user }, { status: 201 });
    response.cookies.set("token", token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      maxAge: 60 * 60 * 24 * 7,
      path: "/",
    });

    return response;
  } catch {
    return NextResponse.json({ error: "Something went wrong" }, { status: 500 });
  }
}

