import { NextResponse } from "next/server";
import { queryOne } from "@/lib/db";

async function fetchGithubContributions(username: string): Promise<number> {
  try {
    const res = await fetch(`https://github.com/users/${username}/contributions`, {
      headers: { "User-Agent": "Mozilla/5.0" }
    });
    if (!res.ok) return 0;
    const text = await res.text();
    const match = text.match(/([\d,]+)\s+contributions\s+in/);
    if (match && match[1]) {
      return parseInt(match[1].replace(/,/g, ""), 10);
    }
    return 0;
  } catch {
    return 0;
  }
}

function getGithubUsername(url: string): string | null {
  try {
    const cleanUrl = url.trim().replace(/\/+$/, "");
    const parts = cleanUrl.split("/");
    return parts[parts.length - 1] || null;
  } catch {
    return null;
  }
}

export async function GET() {
  try {
    const { execute } = await import("@/lib/db");
    await execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS cups_of_coffee VARCHAR(50) DEFAULT '0'");
    await execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS contributions VARCHAR(50) DEFAULT '1k+'");
    await execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS github_last_fetched TIMESTAMP");

    let admin = await queryOne(
      "SELECT id, name, last_name, profile_photo, bio, github_url, linkedin_url, twitter_url, cups_of_coffee, contributions, github_last_fetched FROM users WHERE role = $1 LIMIT 1",
      ["admin"]
    ) as Record<string, any> | null;

    if (admin && admin.github_url) {
      const username = getGithubUsername(admin.github_url);
      if (username) {
        const lastFetched = admin.github_last_fetched ? new Date(admin.github_last_fetched).getTime() : 0;
        const now = Date.now();
        if (now - lastFetched > 3600000) {
          const count = await fetchGithubContributions(username);
          if (count > 0) {
            const formatted = count >= 1000 ? `${(count / 1000).toFixed(1)}k+` : `${count}`;
            await execute(
              "UPDATE users SET contributions = $1, github_last_fetched = NOW() WHERE id = $2",
              [formatted, admin.id]
            );
            admin.contributions = formatted;
          }
        }
      }
    }

    const deliveredCount = await queryOne(
      "SELECT COUNT(*) as count FROM project_requests WHERE status = 'delivered'"
    ) as { count: string | number } | null;

    return NextResponse.json({
      admin: admin ?? null,
      projects_delivered: deliveredCount ? Number(deliveredCount.count) : 0,
      cups_of_coffee: admin?.cups_of_coffee ?? "0",
      contributions: admin?.contributions ?? "1k+",
    });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || "Something went wrong" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { queryOne, execute } from "@/lib/db";
import { getSession } from "@/lib/auth";

export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const user = await getSession();
  if (!user || user.role !== "client") {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const { id } = await params;
    const { rating, content } = await req.json();

    if (!rating || rating < 1 || rating > 5 || !content) {
      return NextResponse.json({ error: "Rating (1-5) and content are required" }, { status: 400 });
    }

    // Check if the project request belongs to this client and is delivered
    const request = await queryOne(
      "SELECT * FROM project_requests WHERE id = $1 AND client_id = $2",
      [id, user.id]
    ) as Record<string, any> | null;

    if (!request) {
      return NextResponse.json({ error: "Project request not found" }, { status: 404 });
    }

    if (request.status !== "delivered") {
      return NextResponse.json({ error: "Reviews can only be added for delivered projects" }, { status: 400 });
    }

    // Check if a review already exists
    const existing = await queryOne("SELECT id FROM reviews WHERE project_request_id = $1", [id]) as { id: number } | null;

    if (existing) {
      await execute(`
        UPDATE reviews 
        SET rating = $1, content = $2, created_at = NOW()
        WHERE id = $3
      `, [rating, content, existing.id]);
      return NextResponse.json({ success: true, updated: true }, { status: 200 });
    }

    // Insert the review
    await execute(`
      INSERT INTO reviews (project_request_id, client_id, rating, content)
      VALUES ($1, $2, $3, $4)
    `, [Number(id), user.id, rating, content]);

    return NextResponse.json({ success: true, created: true }, { status: 201 });
  } catch {
    return NextResponse.json({ error: "Something went wrong" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { queryOne, execute } from "@/lib/db";
import { getSession } from "@/lib/auth";

export async function DELETE(
  _req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const user = await getSession();
  if (!user || user.role !== "admin") {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const { ensureProductsTable } = await import("@/lib/schema");
    await ensureProductsTable();
    const { id } = await params;

    const request = await queryOne("SELECT * FROM project_requests WHERE id = $1", [id]) as Record<string, any> | null;
    if (!request) {
      return NextResponse.json({ error: "Not found" }, { status: 404 });
    }

    if (request.status === "delivered") {
      return NextResponse.json({ error: "Delivered projects cannot be deleted. They are archived in the Delivered Projects page." }, { status: 400 });
    }

    const conversationId = request.conversation_id;

    // Nullify conversation FK on project request first, then delete conversation tree
    if (conversationId) {
      await execute("UPDATE project_requests SET conversation_id = NULL WHERE id = $1", [Number(id)]);
      await execute("DELETE FROM messages WHERE conversation_id = $1", [conversationId]);
      await execute("DELETE FROM conversations WHERE id = $1", [conversationId]);
    }

    // Delete the project request
    await execute("DELETE FROM project_requests WHERE id = $1", [Number(id)]);

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error("[DELETE PROJECT REQUEST ERROR]", err?.message || err);
    return NextResponse.json({ error: `Something went wrong: ${err?.message || "Unknown"}` }, { status: 500 });
  }
}

export async function PATCH(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const user = await getSession();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const { ensureProductsTable } = await import("@/lib/schema");
    await ensureProductsTable();
    const { id } = await params;
    const request = await queryOne("SELECT * FROM project_requests WHERE id = $1", [id]) as Record<string, any> | null;

    if (!request) {
      return NextResponse.json({ error: "Not found" }, { status: 404 });
    }

    const body = await req.json();

    // Client action: sign contract or upload final payment
    if (user.role !== "admin") {
      if (request.client_id !== user.id) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
      }

      const { contract_signed, contract_signed_name, final_payment_receipt_url, final_payment_reference_no, payment_receipt_url, payment_reference_no, payment_method_id } = body;

      // Downpayment receipt upload (client pays after submitting request)
      if (payment_receipt_url !== undefined) {
        if (!payment_receipt_url || !payment_reference_no) {
          return NextResponse.json({ error: "Receipt image and reference number are required" }, { status: 400 });
        }

        await execute(
          `UPDATE project_requests 
           SET payment_receipt_url = $1, 
               payment_reference_no = $2, 
               payment_method_id = $3,
               receipt_verified = FALSE,
               updated_at = NOW() 
           WHERE id = $4`,
          [payment_receipt_url, payment_reference_no.trim(), payment_method_id || null, Number(id)]
        );

        if (request.conversation_id) {
          const msg = `≡ƒÆ░ Downpayment receipt uploaded! Transaction reference: "${payment_reference_no.trim()}".`;
          await execute(
            "INSERT INTO messages (conversation_id, sender_id, content) VALUES ($1, $2, $3)",
            [request.conversation_id, user.id, msg]
          );
          await execute(
            "UPDATE conversations SET last_message = $1, last_message_at = NOW() WHERE id = $2",
            [msg, request.conversation_id]
          );
        }

        return NextResponse.json({ success: true });
      }

      // Final payment receipt upload
      if (final_payment_receipt_url !== undefined) {
        if (!final_payment_receipt_url || !final_payment_reference_no) {
          return NextResponse.json({ error: "Receipt image and reference number are required" }, { status: 400 });
        }

        // --- FAKE RECEIPT DETECTOR SCAN ---
        const invalidKeywords = ["fake", "dummy", "test", "mock", "sample", "fabricated", "screenshot_123", "placeholder"];
        const fileLower = final_payment_receipt_url.toLowerCase();
        const refLower = final_payment_reference_no.toLowerCase();

        const containsFakeKeyword = invalidKeywords.some(
          (kw) => fileLower.includes(kw) || refLower.includes(kw)
        );

        const refClean = final_payment_reference_no.trim();
        const isValidRefFormat = /^[a-zA-Z0-9-]{8,24}$/.test(refClean);

        if (containsFakeKeyword || !isValidRefFormat) {
          return NextResponse.json(
            { error: "Fake Receipt Detected: Our automated payment scanner flagged this receipt or transaction reference as invalid. Please verify and upload your actual banking receipt." },
            { status: 400 }
          );
        }
        // ----------------------------------

        await execute(
          `UPDATE project_requests 
           SET final_payment_receipt_url = $1, 
               final_payment_reference_no = $2, 
               final_receipt_verified = TRUE,
               updated_at = NOW() 
           WHERE id = $3`,
          [final_payment_receipt_url, refClean, Number(id)]
        );

        // Send chat message on final payment
        if (request.conversation_id) {
          const msg = `≡ƒÆ░ I have uploaded the final 50% payment receipt! Transaction reference: "${refClean}".`;
          await execute(
            "INSERT INTO messages (conversation_id, sender_id, content) VALUES ($1, $2, $3)",
            [request.conversation_id, user.id, msg]
          );
          await execute(
            "UPDATE conversations SET last_message = $1, last_message_at = NOW() WHERE id = $2",
            [msg, request.conversation_id]
          );
        }

        return NextResponse.json({ success: true });
      }

      // Contract signature
      if (contract_signed !== undefined) {
        const { contract_signature_url } = body;
        await execute(
          `UPDATE project_requests 
           SET contract_signed = $1, 
               contract_signed_name = $2, 
               contract_signature_url = $3,
               contract_signed_at = CASE WHEN $1 = TRUE THEN NOW() ELSE NULL END,
               contract_signed_acknowledged = FALSE,
               updated_at = NOW() 
           WHERE id = $4`,
          [!!contract_signed, contract_signed_name || null, contract_signature_url || null, Number(id)]
        );

        // Send chat message on contract signature
        if (contract_signed && request.conversation_id) {
          const msg = `Γ£ì∩╕Å I have signed the project agreement contract!`;
          await execute(
            "INSERT INTO messages (conversation_id, sender_id, content) VALUES ($1, $2, $3)",
            [request.conversation_id, user.id, msg]
          );
          await execute(
            "UPDATE conversations SET last_message = $1, last_message_at = NOW() WHERE id = $2",
            [msg, request.conversation_id]
          );
        }

        return NextResponse.json({ success: true });
      }

      return NextResponse.json({ error: "Invalid action" }, { status: 400 });
    }

    // Admin actions
    const { status, contract_signed_acknowledged, receipt_verified, payment_rejection_reason } = body;

    // Payment validation (admin accepts or rejects downpayment receipt)
    if (receipt_verified === true) {
      await execute(
        `UPDATE project_requests 
         SET receipt_verified = TRUE, 
             status = 'accepted', 
             updated_at = NOW() 
         WHERE id = $1`,
        [Number(id)]
      );

      if (request.conversation_id) {
        const msg = "Γ£à Downpayment verified! Your project request has been accepted. ≡ƒÄë Please sign the project agreement contract.";
        await execute(
          "INSERT INTO messages (conversation_id, sender_id, content) VALUES ($1, $2, $3)",
          [request.conversation_id, user.id, msg]
        );
        await execute(
          "UPDATE conversations SET last_message = $1, last_message_at = NOW() WHERE id = $2",
          [msg, request.conversation_id]
        );
      }

      return NextResponse.json({ success: true });
    }

    if (receipt_verified === false) {
      if (!payment_rejection_reason) {
        return NextResponse.json({ error: "Rejection reason is required when rejecting payment." }, { status: 400 });
      }

      await execute(
        `UPDATE project_requests 
         SET receipt_verified = FALSE, 
             payment_rejection_reason = $1,
             status = 'rejected', 
             rejection_reason = $1,
             updated_at = NOW() 
         WHERE id = $2`,
        [payment_rejection_reason.trim(), Number(id)]
      );

      if (request.conversation_id) {
        const msg = `Γ¥î Your downpayment has been rejected. Developer's note: "${payment_rejection_reason.trim()}". Please contact the developer for refund arrangements.`;
        await execute(
          "INSERT INTO messages (conversation_id, sender_id, content) VALUES ($1, $2, $3)",
          [request.conversation_id, user.id, msg]
        );
        await execute(
          "UPDATE conversations SET last_message = $1, last_message_at = NOW() WHERE id = $2",
          [msg, request.conversation_id]
        );
      }

      return NextResponse.json({ success: true });
    }

    if (contract_signed_acknowledged !== undefined) {
      await execute(
        "UPDATE project_requests SET contract_signed_acknowledged = $1, updated_at = NOW() WHERE id = $2",
        [!!contract_signed_acknowledged, Number(id)]
      );
      return NextResponse.json({ success: true });
    }

    if (status !== undefined) {
      const validStatuses = ["pending", "accepted", "rejected", "in_progress", "testing", "completed", "delivered"];
      if (!validStatuses.includes(status)) {
        return NextResponse.json({ error: "Invalid status" }, { status: 400 });
      }

      // Escrow / status lock checks
      if (status === "delivered") {
        if (!request.contract_signed) {
          return NextResponse.json({ error: "Contract unsigned: Client must sign the contract before project handover." }, { status: 400 });
        }
        if (!request.final_payment_receipt_url) {
          return NextResponse.json({ error: "Final payment pending: Client must complete final payment before marking as delivered." }, { status: 400 });
        }
      }

      const { rejection_reason } = body;

      const isRejected = status === "rejected";
      await execute(
        `UPDATE project_requests 
         SET status = $1, 
             rejection_reason = CASE WHEN $2 THEN $3 ELSE NULL END, 
             updated_at = NOW() 
         WHERE id = $4`,
        [status, isRejected, rejection_reason || null, Number(id)]
      );

      // Send chat message on accept/reject
      if (request.conversation_id) {
        let msg = "";
        if (status === "accepted") {
          msg = "Your project request has been accepted! ≡ƒÄë Please sign the project agreement contract.";
        } else if (status === "rejected") {
          msg = rejection_reason 
            ? `Your project request has been rejected. Note from developer: "${rejection_reason}"`
            : "Your project request has been rejected.";
        }
        if (msg) {
          await execute(
            "INSERT INTO messages (conversation_id, sender_id, content) VALUES ($1, $2, $3)",
            [request.conversation_id, user.id, msg]
          );
          await execute(
            "UPDATE conversations SET last_message = $1, last_message_at = NOW() WHERE id = $2",
            [msg, request.conversation_id]
          );
        }
      }
      return NextResponse.json({ success: true });
    }

    return NextResponse.json({ error: "No action provided" }, { status: 400 });
  } catch (err: any) {
    console.error("[PATCH PROJECT REQUEST ERROR]", err?.message || err);
    return NextResponse.json({ error: `Something went wrong: ${err?.message || "Unknown"}` }, { status: 500 });
  }
}

