  tech_stack: string;
  status: string;
  conversation_id: number | null;
  created_at: string;
  client_name: string;
  client_email: string;
  package_tier?: string;
  project_baseline?: string;
  est_timeline?: string;
  deliverables?: string;
  contract_signed?: boolean;
  contract_signed_name?: string | null;
  contract_signed_at?: string | null;
  contract_signature_url?: string | null;
