                  <p className="text-xs text-zinc-300">
                    <span className="font-semibold text-white">Reference No:</span> {selected.payment_reference_no || "N/A"}
                  </p>
                  <a
                    href={selected.payment_receipt_url}
                    target="_blank"
                    rel="noreferrer"
                    className="inline-block text-[10px] text-cyan-400 hover:underline"
                  >
                    View Downpayment Screenshot Γåù
                  </a>
                </div>
              ) : null}

              {/* Final Payment Receipt */}
              {selected.final_payment_receipt_url ? (
                <div className="border-t border-white/5 pt-4 space-y-1.5 text-left">
                  <p className="text-xs text-zinc-500">Final 50% Payment Receipt</p>
                  <p className="text-xs text-zinc-300">
                    <span className="font-semibold text-white">Reference No:</span> {selected.final_payment_reference_no || "N/A"}
                  </p>
                  <a
                    href={selected.final_payment_receipt_url}
                    target="_blank"
                    rel="noreferrer"
                    className="inline-block text-[10px] text-cyan-400 hover:underline"
                  >
                    View Final Payment Screenshot Γåù
                  </a>
                </div>
              ) : null}

              {(selected.status === "accepted" || selected.status === "in_progress" || selected.status === "testing" || selected.status === "completed" || selected.status === "delivered") && (
                <div>
                  <p className="text-xs text-zinc-500">Contract Agreement Status</p>
                  <div className="mt-1.5 space-y-2 text-left">
                    {selected.contract_signed ? (
                      <div>
                        <p className="text-xs text-green-400 font-semibold">
                          Γ£ô Signed by <span className="underline font-bold text-white">{selected.contract_signed_name}</span> on {new Date(selected.contract_signed_at || "").toLocaleDateString()}
                        </p>
                        {selected.contract_signature_url && (
                          <img src={selected.contract_signature_url} alt="Client signature" className="mt-2 h-10 w-auto rounded-lg border border-white/5 bg-white p-1" />
                        )}
                      </div>
                    ) : (
                      <p className="text-xs text-yellow-500 italic">Pending Client Signature</p>
                    )}
                    <button
                      onClick={() => printContract(selected)}
                      className="rounded-lg border border-white/10 px-3 py-1.5 text-[10px] font-bold text-zinc-300 transition-colors hover:border-white/20 hover:text-white"
                    >
                      Print / Download Contract
                    </button>
                  </div>
                </div>
              )}
            </div>

            <div className="mt-6 flex flex-wrap items-center gap-3 border-t border-white/10 pt-4">
              {/* Payment Validation ΓÇö receipt uploaded, admin must accept or reject */}
              {selected.status === "pending" && selected.payment_receipt_url && (
                rejectingId === selected.id ? (
                  <div className="w-full space-y-3 bg-zinc-900/40 p-4 rounded-xl border border-red-500/10 text-left">
                    <div className="rounded-lg bg-red-500/10 border border-red-500/20 p-3 text-[11px] text-red-400">
                      <p className="font-semibold text-white mb-1">Refund Notice</p>
                      <p>If you reject this payment, the client will be notified and a <strong className="text-white">refund will be processed</strong> for the downpayment amount.</p>
                    </div>
                    <label className="block text-[10px] font-semibold text-zinc-500 uppercase tracking-wider">Reason for Payment Rejection</label>
                    <textarea
                      rows={3}
                      placeholder="e.g. Receipt is unclear. Please upload a clearer screenshot."
                      value={rejectionReasonInput}
                      onChange={(e) => setRejectionReasonInput(e.target.value)}
                      required
                      className="glass w-full resize-none rounded-xl px-3 py-2 text-xs text-white placeholder-zinc-500 outline-none focus:border-red-500/30 bg-zinc-950"
                    />
                    <div className="flex justify-end gap-2">
                      <button
                        onClick={() => { setRejectingId(null); setRejectionReasonInput(""); }}
                        className="rounded-lg border border-white/10 px-3 py-1.5 text-[10px] font-semibold text-zinc-400 transition-colors hover:text-white"
                      >
                        Cancel
                      </button>
                      <button
                        onClick={() => submitPaymentRejection(selected.id)}
                        className="rounded-lg bg-red-600 px-3 py-1.5 text-[10px] font-bold text-white transition-opacity hover:opacity-90"
                      >
                        Reject Payment & Refund
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className="flex gap-2 w-full">
                    <button
                      onClick={() => acceptPayment(selected.id)}
                      className="inline-flex items-center gap-1.5 rounded-xl bg-green-500/20 px-4 py-2 text-xs font-medium text-green-400 transition-colors hover:bg-green-500/30 flex-1"
                    >
                      <Check className="h-3.5 w-3.5" /> Accept Payment
                    </button>
                    <button
                      onClick={() => setRejectingId(selected.id)}
                      className="inline-flex items-center gap-1.5 rounded-xl bg-red-500/20 px-4 py-2 text-xs font-medium text-red-400 transition-colors hover:bg-red-500/30 flex-1"
                    >
                      <XCircle className="h-3.5 w-3.5" /> Reject Payment
                    </button>
                  </div>
                )
              )}

              {/* Initial request ΓÇö no receipt yet, simple accept/reject */}
              {selected.status === "pending" && !selected.payment_receipt_url && (
                rejectingId === selected.id ? (
                  <div className="w-full space-y-3 bg-zinc-900/40 p-4 rounded-xl border border-red-500/10 text-left">
                    <label className="block text-[10px] font-semibold text-zinc-500 uppercase tracking-wider">Reason for Rejection (Optional)</label>
                    <textarea
                      rows={3}
                      placeholder="e.g. Current workload is too high. Let's chat next month!"
                      value={rejectionReasonInput}
                      onChange={(e) => setRejectionReasonInput(e.target.value)}
                      className="glass w-full resize-none rounded-xl px-3 py-2 text-xs text-white placeholder-zinc-500 outline-none focus:border-red-500/30 bg-zinc-950"
                    />
                    <div className="flex justify-end gap-2">
                      <button
                        onClick={() => { setRejectingId(null); setRejectionReasonInput(""); }}
                        className="rounded-lg border border-white/10 px-3 py-1.5 text-[10px] font-semibold text-zinc-400 transition-colors hover:text-white"
                      >
                        Cancel
                      </button>
                      <button
                        onClick={() => submitRejection(selected.id)}
                        className="rounded-lg bg-red-600 px-3 py-1.5 text-[10px] font-bold text-white transition-opacity hover:opacity-90"
                      >
                        Confirm Reject
                      </button>
                    </div>
                  </div>
                ) : (
                  <>
                    <button
                      onClick={() => updateStatus(selected.id, "accepted")}
                      className="inline-flex items-center gap-1.5 rounded-xl bg-green-500/20 px-4 py-2 text-xs font-medium text-green-400 transition-colors hover:bg-green-500/30"
                    >
                      <Check className="h-3.5 w-3.5" /> Accept
                    </button>
                    <button
                      onClick={() => setRejectingId(selected.id)}
                      className="inline-flex items-center gap-1.5 rounded-xl bg-red-500/20 px-4 py-2 text-xs font-medium text-red-400 transition-colors hover:bg-red-500/30"
                    >
                      <XCircle className="h-3.5 w-3.5" /> Reject Request
                    </button>
                  </>
                )
              )}

              {selected.status === "accepted" && !selected.contract_signed && (
                <button
                  onClick={() => setRejectingId(selected.id)}
                  className="inline-flex items-center gap-1.5 rounded-xl bg-red-500/20 px-4 py-2 text-xs font-medium text-red-400 transition-colors hover:bg-red-500/30"
                >
                  <XCircle className="h-3.5 w-3.5" /> Reject Request
                </button>
              )}

              {selected.status !== "pending" && selected.status !== "rejected" && (() => {
                const isProgressDisabled = !selected.contract_signed;
                return (
                  <div className="ml-auto">
                    <button
                      disabled={isProgressDisabled}
                      onClick={() => setOpenDropdown(selected.id)}
                      className={`inline-flex items-center gap-1.5 rounded-xl bg-cyan-500/20 px-4 py-2 text-xs font-medium text-cyan-400 transition-colors hover:bg-cyan-500/30 ${
                        isProgressDisabled ? "opacity-40 cursor-not-allowed" : ""
                      }`}
                      title={isProgressDisabled ? "Progress updates are locked until the client signs the contract agreement." : undefined}
                    >
                      Set Progress <ChevronDown className="h-3 w-3" />
                    </button>
                  </div>
                );
              })()}

              {/* Delete */}
              <button
                onClick={() => deleteRequest(selected.id)}
                className="inline-flex items-center gap-1.5 rounded-xl bg-red-500/10 px-4 py-2 text-xs font-medium text-red-400 transition-colors hover:bg-red-500/20 ml-auto"
              >
                <Trash2 className="h-3.5 w-3.5" /> Delete
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Progress Modal */}
      {openDropdown && selected && (
        <div
          className="fixed inset-0 z-[60] flex items-center justify-center bg-black/60 px-4"
          onClick={() => setOpenDropdown(null)}
        >
          <div
            className="glass-strong w-full max-w-sm rounded-2xl p-6"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-white">Set Progress</h3>
              <button onClick={() => setOpenDropdown(null)} className="text-zinc-500 transition-colors hover:text-white">
                <X className="h-5 w-5" />
              </button>
            </div>
            <p className="text-xs text-zinc-500 mb-4">
              {selected.project_name}
            </p>
            <div className="space-y-2">
              {progressOptions.map((opt) => {
                const isDeliveredDisabled = opt === "delivered" && !selected.final_payment_receipt_url;
                const isCurrent = selected.status === opt;
                return (
                  <button
                    key={opt}
                    disabled={isDeliveredDisabled || isCurrent}
                    onClick={() => updateStatus(selected.id, opt)}
                    className={`flex w-full items-center justify-between rounded-xl px-4 py-3 text-left text-sm transition-colors ${
                      isCurrent
                        ? "bg-cyan-500/20 text-cyan-400 cursor-default"
                        : isDeliveredDisabled
                          ? "bg-zinc-800/50 text-zinc-600 opacity-40 cursor-not-allowed"
                          : "bg-white/5 text-zinc-300 hover:bg-white/10 hover:text-white"
                    }`}
                    title={isDeliveredDisabled ? "Final payment receipt screenshot is required before delivery." : undefined}
                  >
                    <span className="font-medium capitalize">{opt.replace("_", " ")}</span>
                    {isCurrent && <Check className="h-4 w-4 text-cyan-400" />}
                    {isDeliveredDisabled && <span className="text-[10px] text-zinc-600">Locked</span>}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Plus, Pencil, Trash2, X, Code2, Shield, Server, Globe, Database, GitBranch, Smartphone, Palette, Cloud, Braces, Layers, Rocket } from "lucide-react";
import Skeleton from "@/components/Skeleton";

const iconOptions = ["Code2", "Shield", "Server", "Globe", "Database", "GitBranch", "Smartphone", "Palette", "Cloud", "Braces", "Layers", "Rocket"];

interface Service {
  id: number;
  title: string;
  description: string;
  icon: string;
}

export default function ServicesPage() {
  const [services, setServices] = useState<Service[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState<Service | null>(null);
  const [form, setForm] = useState({ title: "", description: "", best_for: "", icon: "Code2" });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    fetch("/api/services")
      .then((r) => r.json())
      .then((d) => { setServices(d.services); setLoading(false); });
  }, []);

  const openAdd = () => {
    setEditing(null);
    setForm({ title: "", description: "", best_for: "", icon: "Code2" });
    setShowModal(true);
  };

  const openEdit = (s: Service) => {
    setEditing(s);
    const parts = s.description.split("|").map((p: string) => p.trim());
    const desc = parts[0]?.replace("What's Included: ", "") || s.description;
    const best = parts[1]?.replace("Best For: ", "") || "";
    setForm({ title: s.title, description: desc, best_for: best, icon: s.icon });
    setShowModal(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    const fullDesc = form.best_for
      ? `What's Included: ${form.description} | Best For: ${form.best_for}`
      : `What's Included: ${form.description}`;
    try {
      if (editing) {
        await fetch(`/api/services/${editing.id}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...form, description: fullDesc }),
        });
        setServices((p) =>
          p.map((s) => (s.id === editing.id ? { ...s, ...form, description: fullDesc } : s))
        );
      } else {
        const res = await fetch("/api/services", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...form, description: fullDesc }),
        });
        const data = await res.json();
        setServices((p) => [...p, { id: data.id, ...form, description: fullDesc }]);
      }
      setShowModal(false);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm("Delete this service?")) return;
    const res = await fetch(`/api/services/${id}`, { method: "DELETE" });
    if (res.ok) setServices((p) => p.filter((s) => s.id !== id));
  };

  const iconMap: Record<string, React.ElementType> = {
    Code2, Shield, Server, Globe, Database, GitBranch, Smartphone, Palette, Cloud, Braces, Layers, Rocket,
  };

  if (loading) {
    return (
      <div className="px-6 py-24">
        <div className="flex items-center justify-between">
          <div className="space-y-2">
            <Skeleton className="h-8 w-40" />
            <Skeleton className="h-4 w-64" />
          </div>
          <Skeleton className="h-11 w-36 rounded-xl" />
        </div>
        <div className="mt-8 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="glass rounded-2xl p-6">
              <div className="flex items-start justify-between">
                <Skeleton className="h-10 w-10 rounded-lg" />
                <div className="flex gap-1">
                  <Skeleton className="h-7 w-7 rounded-lg" />
                  <Skeleton className="h-7 w-7 rounded-lg" />
                </div>
              </div>
              <Skeleton className="mt-4 h-5 w-3/4" />
              <Skeleton className="mt-2 h-4 w-full" />
              <Skeleton className="mt-1 h-4 w-1/2" />
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="px-6 py-24">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white">Services</h1>
          <p className="mt-1 text-sm text-zinc-400">
            Manage the services displayed on your portfolio.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={openAdd}
            className="inline-flex items-center gap-2 rounded-xl bg-gradient-to-r from-cyan-500 to-blue-600 px-5 py-2.5 text-sm font-medium text-white transition-opacity hover:opacity-90"
          >
            <Plus className="h-4 w-4" />
            Add Service
          </button>
        </div>
      </div>

      <div className="mt-8 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {services.length === 0 ? (
          <div className="col-span-full py-16 text-center text-zinc-500">
            No services yet. Click "Add Service" to add one manually.
          </div>
        ) : (
          services.map((s) => {
            const Icon = iconMap[s.icon] || Code2;
            const parts = s.description.split("|").map((p: string) => p.trim());
            const desc = parts[0]?.replace("What's Included: ", "") || s.description;
            const bestFor = parts[1]?.replace("Best For: ", "") || "";
            return (
              <div key={s.id} className="glass rounded-2xl p-6 transition-all glass-hover">
                <div className="flex items-start justify-between">
                  <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-gradient-to-br from-cyan-500/20 to-blue-600/20">
                    <Icon className="h-5 w-5 text-cyan-400" />
                  </div>
                  <div className="flex gap-1">
                    <button onClick={() => openEdit(s)} className="rounded-lg p-1.5 text-zinc-500 transition-colors hover:text-cyan-400">
                      <Pencil className="h-4 w-4" />
                    </button>
                    <button onClick={() => handleDelete(s.id)} className="rounded-lg p-1.5 text-zinc-500 transition-colors hover:text-red-400">
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </div>
                </div>
                <h3 className="mt-4 font-semibold text-white">{s.title}</h3>
                <p className="mt-2 text-sm leading-relaxed text-zinc-400">{desc}</p>
                {bestFor && (
                  <div className="mt-4 border-t border-white/5 pt-3">
                    <h4 className="text-[10px] font-semibold text-zinc-500 uppercase tracking-wider">Best For</h4>
                    <p className="mt-1 text-xs text-cyan-400/90">{bestFor}</p>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 px-4">
          <div className="glass w-full max-w-lg rounded-2xl p-8">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-semibold text-white">
                {editing ? "Edit Service" : "Add Service"}
              </h3>
              <button onClick={() => setShowModal(false)} className="text-zinc-500 transition-colors hover:text-white">
                <X className="h-5 w-5" />
              </button>
            </div>
            <form onSubmit={handleSave} className="mt-6 space-y-4">
              <input type="text" placeholder="Service Title" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} required className="glass w-full rounded-xl px-4 py-3 text-sm text-white placeholder-zinc-500 outline-none focus:border-cyan-500/50" />
              <textarea rows={3} placeholder="Service Description" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} required className="glass w-full resize-none rounded-xl px-4 py-3 text-sm text-white placeholder-zinc-500 outline-none focus:border-cyan-500/50" />
              <input type="text" placeholder="Best For (e.g., Startups, E-commerce, Portfolios)" value={form.best_for} onChange={(e) => setForm({ ...form, best_for: e.target.value })} className="glass w-full rounded-xl px-4 py-3 text-sm text-white placeholder-zinc-500 outline-none focus:border-cyan-500/50" />
              <div>
                <label className="mb-2 block text-xs text-zinc-500">Icon</label>
                <div className="flex flex-wrap gap-2">
                  {iconOptions.map((ic) => {
                    const Icon = iconMap[ic];
                    return (
                      <button key={ic} type="button" onClick={() => setForm({ ...form, icon: ic })} className={`flex h-10 w-10 items-center justify-center rounded-lg transition-all ${form.icon === ic ? "bg-cyan-500/20 text-cyan-400 ring-1 ring-cyan-500/50" : "glass text-zinc-400 hover:text-white"}`}>
                        <Icon className="h-5 w-5" />
                      </button>
                    );
                  })}
                </div>
              </div>
              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={() => setShowModal(false)} className="rounded-xl border border-white/10 px-6 py-2.5 text-sm font-medium text-zinc-400 transition-colors hover:border-white/20 hover:text-white">Cancel</button>
                <button type="submit" disabled={saving} className="rounded-xl bg-gradient-to-r from-cyan-500 to-blue-600 px-6 py-2.5 text-sm font-medium text-white transition-opacity hover:opacity-90 disabled:opacity-50">{saving ? "Saving..." : "Save"}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Skeleton from "@/components/Skeleton";
import { Eye, Trash2, X } from "lucide-react";

interface User {
  id: number;
  name: string;
  email: string;
  role: string;
  created_at: string;
  oauth_provider?: string | null;
  avatar_url?: string | null;
  profile_photo?: string | null;
  bio?: string | null;
  github_url?: string | null;
  linkedin_url?: string | null;
  twitter_url?: string | null;
}

export default function UserManagement() {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewUser, setViewUser] = useState<User | null>(null);
  const [viewLoading, setViewLoading] = useState(false);
  const [deleteConfirm, setDeleteConfirm] = useState<number | null>(null);
  const [deleting, setDeleting] = useState(false);

  const fetchUsers = () => {
    fetch("/api/users")
      .then((r) => (r.ok ? r.json() : { users: [] }))
      .then((d) => { setUsers(d.users); setLoading(false); });
  };

  useEffect(() => { fetchUsers(); }, []);

  const handleView = async (id: number) => {
    setViewLoading(true);
    setViewUser(null);
    try {
      const res = await fetch(`/api/users/${id}`);
      const data = await res.json();
      setViewUser(data.user);
    } catch {}
    setViewLoading(false);
  };

  const handleDelete = async (id: number) => {
    setDeleting(true);
    try {
      const res = await fetch(`/api/users/${id}`, { method: "DELETE" });
      if (res.ok) {
        setUsers((prev) => prev.filter((u) => u.id !== id));
        setDeleteConfirm(null);
      }
    } catch {}
    setDeleting(false);
  };

  if (loading) {
    return (
      <div className="px-6 py-24">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="mt-1 h-4 w-72" />
        <div className="mt-8 overflow-x-auto">
          <div className="glass w-full rounded-2xl p-5 space-y-4">
            <div className="flex gap-8 border-b border-white/5 pb-4">
              <Skeleton className="h-4 w-8" />
              <Skeleton className="h-4 w-24" />
              <Skeleton className="h-4 w-32" />
              <Skeleton className="h-4 w-12" />
              <Skeleton className="h-4 w-20" />
            </div>
            {Array.from({ length: 5 }).map((_, i) => (
              <div key={i} className="flex gap-8">
                <Skeleton className="h-4 w-8" />
                <Skeleton className="h-4 w-24" />
                <Skeleton className="h-4 w-32" />
                <Skeleton className="h-5 w-14 rounded-full" />
                <Skeleton className="h-4 w-20" />
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="px-6 py-24">
      <h1 className="text-2xl font-bold text-white">User Management</h1>
      <p className="mt-1 text-sm text-zinc-400">
        View all registered users and their roles.
      </p>

      <div className="mt-8 overflow-x-auto">
        <table className="glass w-full rounded-2xl text-left text-sm">
          <thead>
            <tr className="border-b border-white/5 text-zinc-500">
              <th className="px-5 py-3 font-medium">ID</th>
              <th className="px-5 py-3 font-medium">Name</th>
              <th className="px-5 py-3 font-medium">Email</th>
              <th className="px-5 py-3 font-medium">Role</th>
              <th className="px-5 py-3 font-medium">Joined</th>
              <th className="px-5 py-3 font-medium text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.length === 0 ? (
              <tr>
                <td colSpan={6} className="px-5 py-8 text-center text-zinc-500">
                  No users registered yet
                </td>
              </tr>
            ) : (
              users.map((u) => (
                <tr
                  key={u.id}
                  className="border-b border-white/5 text-white last:border-0"
                >
                  <td className="px-5 py-3.5 text-zinc-400">{u.id}</td>
                  <td className="px-5 py-3.5">{u.name}</td>
                  <td className="px-5 py-3.5 text-zinc-400">{u.email}</td>
                  <td className="px-5 py-3.5">
                    <span
                      className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${
                        u.role === "admin"
                          ? "bg-cyan-500/10 text-cyan-400"
                          : "bg-zinc-500/10 text-zinc-400"
                      }`}
                    >
                      {u.role}
                    </span>
                  </td>
                  <td className="px-5 py-3.5 text-zinc-500">
                    {new Date(u.created_at).toLocaleDateString()}
                  </td>
                  <td className="px-5 py-3.5">
                    <div className="flex items-center justify-end gap-2">
                      <button
                        onClick={() => handleView(u.id)}
                        className="rounded-lg p-1.5 text-zinc-400 hover:bg-white/5 hover:text-cyan-400 transition-colors"
                        title="View"
                      >
                        <Eye size={16} />
                      </button>
                      <button
                        onClick={() => setDeleteConfirm(u.id)}
                        className="rounded-lg p-1.5 text-zinc-400 hover:bg-white/5 hover:text-red-400 transition-colors"
                        title="Delete"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* View User Modal */}
      {(viewUser || viewLoading) && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm" onClick={() => { setViewUser(null); setViewLoading(false); }}>
          <div className="glass-strong mx-4 w-full max-w-lg rounded-2xl p-6 shadow-2xl" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-lg font-semibold text-white">User Details</h2>
              <button onClick={() => { setViewUser(null); setViewLoading(false); }} className="text-zinc-400 hover:text-white transition-colors">
                <X size={20} />
              </button>
            </div>
            {viewLoading && !viewUser && (
              <div className="space-y-4">
                <Skeleton className="h-20 w-20 rounded-full mx-auto" />
                <Skeleton className="h-5 w-48 mx-auto" />
                <Skeleton className="h-4 w-64 mx-auto" />
              </div>
            )}
            {viewUser && (
              <div className="space-y-4">
                <div className="flex flex-col items-center gap-3">
                  {viewUser.avatar_url || viewUser.profile_photo ? (
                    <img src={viewUser.avatar_url || viewUser.profile_photo || ""} alt={viewUser.name} className="h-20 w-20 rounded-full object-cover border-2 border-white/10" />
                  ) : (
                    <div className="h-20 w-20 rounded-full bg-gradient-to-br from-cyan-500 to-blue-600 flex items-center justify-center text-2xl font-bold text-white">
                      {viewUser.name?.charAt(0)?.toUpperCase()}
                    </div>
                  )}
                  <div className="text-center">
                    <h3 className="text-white font-semibold text-lg">{viewUser.name}</h3>
                    <p className="text-zinc-400 text-sm">{viewUser.email}</p>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-3 mt-4">
                  <div className="glass rounded-xl p-3">
                    <p className="text-xs text-zinc-500 mb-1">Role</p>
                    <span className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${
                      viewUser.role === "admin" ? "bg-cyan-500/10 text-cyan-400" : "bg-zinc-500/10 text-zinc-400"
                    }`}>{viewUser.role}</span>
                  </div>
                  <div className="glass rounded-xl p-3">
                    <p className="text-xs text-zinc-500 mb-1">Joined</p>
                    <p className="text-sm text-white">{new Date(viewUser.created_at).toLocaleDateString()}</p>
                  </div>
                  <div className="glass rounded-xl p-3">
                    <p className="text-xs text-zinc-500 mb-1">Auth Provider</p>
                    <p className="text-sm text-white">{viewUser.oauth_provider || "Email/Password"}</p>
                  </div>
                  <div className="glass rounded-xl p-3">
                    <p className="text-xs text-zinc-500 mb-1">User ID</p>
                    <p className="text-sm text-white">#{viewUser.id}</p>
                  </div>
                </div>
                {viewUser.bio && (
                  <div className="glass rounded-xl p-3">
                    <p className="text-xs text-zinc-500 mb-1">Bio</p>
                    <p className="text-sm text-white">{viewUser.bio}</p>
                  </div>
                )}
                {(viewUser.github_url || viewUser.linkedin_url || viewUser.twitter_url) && (
                  <div className="glass rounded-xl p-3">
                    <p className="text-xs text-zinc-500 mb-1">Social Links</p>
                    <div className="flex flex-col gap-1 mt-1">
                      {viewUser.github_url && <a href={viewUser.github_url} target="_blank" rel="noopener noreferrer" className="text-sm text-cyan-400 hover:underline">{viewUser.github_url}</a>}
                      {viewUser.linkedin_url && <a href={viewUser.linkedin_url} target="_blank" rel="noopener noreferrer" className="text-sm text-cyan-400 hover:underline">{viewUser.linkedin_url}</a>}
                      {viewUser.twitter_url && <a href={viewUser.twitter_url} target="_blank" rel="noopener noreferrer" className="text-sm text-cyan-400 hover:underline">{viewUser.twitter_url}</a>}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deleteConfirm !== null && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm" onClick={() => setDeleteConfirm(null)}>
          <div className="glass-strong mx-4 w-full max-w-sm rounded-2xl p-6 text-center shadow-2xl" onClick={(e) => e.stopPropagation()}>
            <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-red-500/10 text-red-500">
              <Trash2 className="h-6 w-6" />
            </div>
            <h3 className="text-lg font-semibold text-white">Delete User?</h3>
            <p className="mt-2 text-sm text-zinc-400">
              This action cannot be undone. The user will lose access to their account.
            </p>
            <div className="mt-6 flex gap-3">
              <button
                onClick={() => setDeleteConfirm(null)}
                className="flex-1 rounded-xl border border-white/10 px-4 py-2.5 text-sm font-medium text-zinc-300 transition-colors hover:bg-white/5"
                disabled={deleting}
              >
                Cancel
              </button>
              <button
                onClick={() => handleDelete(deleteConfirm)}
                className="flex-1 rounded-xl bg-gradient-to-r from-red-500 to-red-600 px-4 py-2.5 text-sm font-semibold text-white transition-opacity hover:opacity-90 disabled:opacity-50"
                disabled={deleting}
              >
                {deleting ? "Deleting..." : "Delete"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

