          if (/italic/i.test(lower)) fs = "italic";
          if (/bold/i.test(lower)) fw = "bold";
          const entry = { font_name: fontName, font_url: data.url, font_weight: fw, font_style: fs };
          const idx = prev.findIndex((f) => f.font_name === fontName);
          if (idx >= 0) {
            const updated = [...prev];
            updated[idx] = entry;
            return updated;
          }
          return [...prev, entry];
