// Helper utilities for HSL conversions to generate premium themes dynamically in preview mode
function hexToHsl(hex: string): { h: number; s: number; l: number } {
  hex = hex.replace(/^#/, "");
  let r = parseInt(hex.substring(0, 2), 16) / 255;
  let g = parseInt(hex.substring(2, 4), 16) / 255;
  let b = parseInt(hex.substring(4, 6), 16) / 255;

  let max = Math.max(r, g, b), min = Math.min(r, g, b);
  let h = 0, s = 0, l = (max + min) / 2;

  if (max !== min) {
    let d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r: h = (g - b) / d + (g < b ? 6 : 0); break;
      case g: h = (b - r) / d + 2; break;
      case b: h = (r - g) / d + 4; break;
    }
    h /= 6;
  }

  return { h: Math.round(h * 360), s: Math.round(s * 100), l: Math.round(l * 100) };
}

function hslToHex(h: number, s: number, l: number): string {
  s /= 100;
  l /= 100;
  let c = (1 - Math.abs(2 * l - 1)) * s;
  let x = c * (1 - Math.abs((h / 60) % 2 - 1));
  let m = l - c / 2;
  let r = 0, g = 0, b = 0;

  if (h >= 0 && h < 60) { r = c; g = x; b = 0; }
  else if (h >= 60 && h < 120) { r = x; g = c; b = 0; }
  else if (h >= 120 && h < 180) { r = 0; g = c; b = x; }
  else if (h >= 180 && h < 240) { r = 0; g = x; b = c; }
  else if (h >= 240 && h < 300) { r = x; g = 0; b = c; }
  else if (h >= 300 && h < 360) { r = c; g = 0; b = x; }

  const toHex = (n: number) => {
    let hex = Math.round((n + m) * 255).toString(16);
    return hex.length === 1 ? "0" + hex : hex;
  };
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

"use client";

import { useEffect, useState, useRef } from "react";
import { useRouter, usePathname } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import LoadingOverlay from "@/components/LoadingOverlay";
import Skeleton from "@/components/Skeleton";
import { LayoutDashboard, ClipboardList, Settings, LogOut, Menu } from "lucide-react";

const navItems = [
  { label: "Dashboard", href: "/dashboard/client", icon: LayoutDashboard },
  { label: "Project Requests", href: "/dashboard/client/project-requests", icon: ClipboardList },
  { label: "Profile Settings", href: "/dashboard/client/profile", icon: Settings },
];

export default function ClientLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const [user, setUser] = useState<{ name: string; role: string; profile_photo?: string } | null>(null);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [loggingOut, setLoggingOut] = useState(false);

  useEffect(() => {
    fetch("/api/auth/me")
      .then((r) => (r.ok ? r.json() : null))
      .then((d) => {
        if (!d?.user || d.user.role !== "client") router.push("/login");
        setUser(d.user);
        setLoading(false);
      });
  }, [router]);

  useEffect(() => {
    const handler = () => setMobileOpen((v) => !v);
    window.addEventListener("toggle-mobile-sidebar", handler);
    return () => window.removeEventListener("toggle-mobile-sidebar", handler);
  }, []);

  const sidebarRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const handler = () => setExpanded((v) => !v);
    window.addEventListener("toggle-sidebar-expand", handler);
    return () => window.removeEventListener("toggle-sidebar-expand", handler);
  }, []);

  useEffect(() => {
    if (!expanded) return;
    const handleClick = (e: MouseEvent) => {
      if (sidebarRef.current && !sidebarRef.current.contains(e.target as Node)) {
        setExpanded(false);
      }
    };
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, [expanded]);

  if (loading) {
    return (
      <div className="flex min-h-screen pt-16">
        <aside className="fixed bottom-0 left-0 top-16 z-40 w-16 border-r border-white/5 glass md:flex flex-col items-center py-4 hidden">
          <Skeleton className="h-5 w-5 rounded-lg" />
          <div className="flex flex-col gap-4 mt-6 px-2">
            {Array.from({ length: 3 }).map((_, i) => (
              <Skeleton key={i} className="h-10 w-10 rounded-xl" />
            ))}
          </div>
          <div className="mt-auto">
            <Skeleton className="h-10 w-10 rounded-xl" />
          </div>
        </aside>
        <div className="flex-1 md:pl-16">
          <Skeleton className="h-full w-full" />
        </div>
      </div>
    );
  }

  const showExpanded = expanded || mobileOpen;
  const sidebarWidth = expanded ? "w-64" : "w-16";

  return (
    <div className="flex min-h-screen pt-16">
      <LoadingOverlay show={loggingOut} message="Signing out securely..." />
      {mobileOpen && (
        <div
          className="fixed inset-0 z-30 bg-black/50 md:hidden"
          onClick={() => setMobileOpen(false)}
        />
      )}
      <aside
        ref={sidebarRef}
        className={`fixed bottom-0 left-0 top-16 z-40 border-r border-white/5 glass transition-all duration-300 ${sidebarWidth} max-md:w-64 max-md:-translate-x-full max-md:data-[open]:translate-x-0`}
        data-open={mobileOpen ? "" : undefined}
        onMouseEnter={() => setExpanded(true)}
        onMouseLeave={() => setExpanded(false)}
      >
        <div className="flex flex-col h-full">
          <nav className="flex flex-col gap-1 px-2 pb-4 mt-3">
            {navItems.map((item) => {
              const Icon = item.icon;
              const active = pathname === item.href;
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  onClick={() => { setMobileOpen(false); }}
                  className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-medium transition-all ${
                    showExpanded ? "justify-start" : "justify-center"
                  } ${
                    active
                      ? "bg-gradient-to-r from-cyan-500/20 to-blue-600/20 text-cyan-400"
                      : "text-zinc-400 hover:bg-white/5 hover:text-white"
                  }`}
                  title={showExpanded ? undefined : item.label}
                >
                  <Icon className="h-5 w-5 shrink-0" />
                  {showExpanded && <span className="truncate">{item.label}</span>}
                </Link>
              );
            })}
          </nav>

          <div className="mt-auto border-t border-white/5 p-3">
            {showExpanded ? (
              <div className="flex items-center gap-3 px-1">
                <div className="relative h-8 w-8 shrink-0 rounded-full bg-gradient-to-br from-cyan-500 to-blue-600">
                  {user?.profile_photo ? (
                    <Image src={user.profile_photo} alt="" fill className="rounded-full object-cover" unoptimized />
                  ) : (
                    <div className="flex h-full w-full items-center justify-center text-xs font-bold text-white">
                      {user?.name?.charAt(0)?.toUpperCase() || "C"}
                    </div>
                  )}
                </div>
                <div className="flex-1 truncate">
                  <p className="text-sm text-white">{user?.name}</p>
                  <p className="text-xs text-zinc-500">Client</p>
                </div>
                <button
                  onClick={async () => {
                    setLoggingOut(true);
                    await fetch("/api/auth/logout", { method: "POST" });
                    router.push("/");
                    router.refresh();
                  }}
                  className="text-zinc-500 transition-colors hover:text-red-400"
                >
                  <LogOut className="h-4 w-4" />
                </button>
              </div>
            ) : (
              <div className="flex justify-center">
                <button
                  onClick={async () => {
                    setLoggingOut(true);
                    await fetch("/api/auth/logout", { method: "POST" });
                    router.push("/");
                    router.refresh();
                  }}
                  className="rounded-lg p-2 text-zinc-400 transition-colors hover:text-red-400"
                  title="Logout"
                >
                  <LogOut className="h-5 w-5" />
                </button>
              </div>
            )}
          </div>
        </div>
      </aside>

      <div className={`flex-1 transition-all duration-300 ${expanded ? "md:pl-64" : "md:pl-16"}`}>
        {children}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Skeleton from "@/components/Skeleton";
import { ClipboardList, FileText, MessageSquare, Settings, Star, Wrench } from "lucide-react";
import Link from "next/link";

const formatDate = (dateVal: any) => {
  if (!dateVal) return "N/A";
  const d = new Date(dateVal);
  return isNaN(d.getTime()) ? "N/A" : d.toLocaleDateString();
};

interface ProjectRequest {
  id: number;
  project_name: string;
  description: string;
  tech_stack: string;
  status: string;
  created_at: string;
  rating?: number | null;
  review_content?: string | null;
  contract_signed?: boolean;
}

interface User {
  id: number;
  name: string;
  email: string;
  role: string;
  last_name?: string;
  profile_photo?: string;
}

interface AdminProfile {
  name: string;
  last_name?: string;
  profile_photo?: string;
  bio?: string;
  projects_delivered: number;
}

interface Service {
  id: number;
  title: string;
  description: string;
  icon?: string;
}

const statusColors: Record<string, string> = {
  pending: "bg-yellow-500/10 text-yellow-400",
  accepted: "bg-green-500/10 text-green-400",
  rejected: "bg-red-500/10 text-red-400",
  in_progress: "bg-blue-500/10 text-blue-400",
  testing: "bg-purple-500/10 text-purple-400",
  completed: "bg-cyan-500/10 text-cyan-400",
  delivered: "bg-emerald-500/10 text-emerald-400",
};

const statusLabels: Record<string, string> = {
  pending: "Pending",
  accepted: "Accepted",
  rejected: "Rejected",
  in_progress: "In Progress",
  testing: "Testing",
  completed: "Completed",
  delivered: "Delivered",
};

export default function ClientDashboard() {
  const [user, setUser] = useState<User | null>(null);
  const [requests, setRequests] = useState<ProjectRequest[]>([]);
  const [adminProfile, setAdminProfile] = useState<AdminProfile | null>(null);
  const [services, setServices] = useState<Service[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([
      fetch("/api/auth/me").then((r) => r.json()),
      fetch("/api/project-requests").then((r) => r.json()),
      fetch("/api/profile/public").then((r) => r.json()),
      fetch("/api/services").then((r) => r.json()),
    ])
      .then(([meData, requestsData, profileData, servicesData]) => {
        setUser(meData.user);
        setRequests(requestsData.requests || []);
        setAdminProfile(profileData.admin);
        setServices((servicesData.services || []).slice(0, 4));
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const pendingCount = requests.filter((r) => r.status === "pending").length;
  const inProgressCount = requests.filter(
    (r) => r.status === "in_progress" || r.status === "testing"
  ).length;
  const completedCount = requests.filter(
    (r) => r.status === "completed" || r.status === "delivered"
  ).length;
  const recentRequests = requests.slice(0, 5);

  const statCards = [
    {
      label: "Total Requests",
      value: requests.length,
      icon: ClipboardList,
      color: "from-cyan-500 to-blue-600",
    },
    {
      label: "Pending",
      value: pendingCount,
      icon: FileText,
      color: "from-yellow-500 to-orange-600",
    },
    {
      label: "In Progress",
      value: inProgressCount,
      icon: Wrench,
      color: "from-blue-500 to-purple-600",
    },
    {
      label: "Completed",
      value: completedCount,
      icon: Star,
      color: "from-emerald-500 to-green-600",
    },
  ];

  if (loading) {
    return (
      <div className="px-6 py-24 space-y-10">
        <div className="space-y-3">
          <Skeleton className="h-8 w-64" />
          <Skeleton className="h-4 w-96" />
        </div>
        <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="glass rounded-2xl p-5">
              <div className="flex items-center gap-3">
                <Skeleton className="h-10 w-10 rounded-xl" />
                <div className="space-y-2">
                  <Skeleton className="h-7 w-12" />
                  <Skeleton className="h-3 w-16" />
                </div>
              </div>
            </div>
          ))}
        </div>
        <div className="grid gap-8 lg:grid-cols-3">
          <div className="lg:col-span-2 space-y-4">
            <div className="flex items-center justify-between">
              <Skeleton className="h-6 w-40" />
              <Skeleton className="h-4 w-16" />
            </div>
            <div className="glass rounded-2xl divide-y divide-white/5">
              {Array.from({ length: 4 }).map((_, i) => (
                <div key={i} className="flex items-center justify-between px-5 py-4">
                  <div className="space-y-2">
                    <Skeleton className="h-4 w-48" />
                    <Skeleton className="h-3 w-32" />
                  </div>
                  <Skeleton className="h-5 w-20 rounded-full" />
                </div>
              ))}
            </div>
          </div>
          <div className="space-y-6">
            <div className="glass rounded-2xl p-5 space-y-4">
              <Skeleton className="h-4 w-20" />
              <div className="flex items-center gap-3">
                <Skeleton className="h-12 w-12 rounded-full" />
                <div className="space-y-1.5">
                  <Skeleton className="h-4 w-28" />
                  <Skeleton className="h-3 w-44" />
                </div>
              </div>
              <Skeleton className="h-10 w-full rounded-xl" />
            </div>
            <div className="glass rounded-2xl p-5 space-y-3">
              <Skeleton className="h-4 w-16" />
              {Array.from({ length: 2 }).map((_, i) => (
                <Skeleton key={i} className="h-12 w-full rounded-xl" />
              ))}
            </div>
            <div className="glass rounded-2xl p-5 space-y-3">
              <Skeleton className="h-4 w-20" />
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-10 w-full rounded-xl" />
              ))}
            </div>
          </div>
        </div>
      </div>
    );
  }

  const unsignedContracts = requests.filter(r => r.status === "accepted" && !r.contract_signed);

  return (
    <div className="px-6 py-24 space-y-10">
      {/* Welcome */}
      <div>
        <h1 className="text-2xl font-bold text-white">
          Welcome back{user?.name ? `, ${user.name.split(" ")[0]}` : ""}!
        </h1>
        <p className="mt-1 text-sm text-zinc-400">
          Here&apos;s an overview of your project requests and account.
        </p>
      </div>

      {unsignedContracts.length > 0 && (
        <div className="rounded-2xl border border-yellow-500/25 bg-yellow-500/5 p-5 shadow-lg shadow-yellow-500/5 flex flex-col sm:flex-row items-center justify-between gap-4 animate-pulse">
          <div className="flex items-center gap-3.5">
            <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-yellow-500/10 text-yellow-400">
              <FileText className="h-5.5 w-5.5" />
            </div>
            <div className="text-left">
              <p className="text-sm font-bold text-white">Action Required: Review & Sign Contract</p>
              <p className="text-xs text-zinc-400 mt-0.5">
                You have {unsignedContracts.length} accepted project request(s) waiting for contract signatures.
              </p>
            </div>
          </div>
          <Link
            href="/dashboard/client/project-requests"
            className="rounded-xl bg-gradient-to-r from-yellow-500 to-orange-600 px-5 py-2.5 text-xs font-semibold text-white transition-opacity hover:opacity-90 shrink-0"
          >
            Sign Contract Agreement
