};

function detectCurrency(): string {
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
    if (tz && TZ_CURRENCY_MAP[tz]) return TZ_CURRENCY_MAP[tz];
    if (tz && tz.startsWith("Asia/")) return "PHP";
    if (tz && tz.startsWith("Europe/")) return "EUR";
    if (tz && tz.startsWith("America/")) return "USD";
    if (tz && tz.startsWith("Australia/")) return "AUD";
    if (tz && tz.startsWith("Pacific/")) return "NZD";
    if (tz && tz.startsWith("Africa/")) return "ZAR";
  } catch {}
  return "USD";
}

async function fetchRate(currency: string): Promise<number> {
  if (currency === "USD") return 1;
  try {
    const res = await fetch("https://open.er-api.com/v6/latest/USD");
    const data = await res.json();
    if (data.rates && data.rates[currency]) return data.rates[currency];
  } catch {}
  return 1;
}

export function useLocalCurrency() {
  const [currency, setCurrency] = useState("USD");
  const [rate, setRate] = useState(1);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    const cur = detectCurrency();
    setCurrency(cur);
    fetchRate(cur).then((r) => { setRate(r); setLoaded(true); });
  }, []);

  const formatPrice = (baseline: string) => {
    if (currency === "USD" || rate === 1) return baseline;
    const numbers = baseline.replace(/,/g, "").match(/\d+/g);
    if (!numbers || numbers.length === 0) return baseline;

    const convertedNumbers = numbers.map((n) => {
      const num = Number(n);
      const converted = Math.round(num * rate);
      return new Intl.NumberFormat(undefined, {
        style: "currency",
        currency,
        maximumFractionDigits: 0,
      }).format(converted);
    });

    if (convertedNumbers.length === 2) {
      return `${convertedNumbers[0]} ΓÇô ${convertedNumbers[1]}${baseline.includes("+") ? "+" : ""}`;
    } else if (convertedNumbers.length === 1) {
      return `${convertedNumbers[0]}${baseline.includes("+") ? "+" : ""}`;
    }
    return baseline;
  };

  const formatDownpayment = (baseline: string) => {
    const nums = baseline.replace(/[$,]/g, "").match(/\d+/g);
    if (!nums) return null;
    const minPrice = parseInt(nums[0], 10);
    const half = Math.round(minPrice / 2);
    if (currency === "USD" || rate === 1) {
      return `$${half.toLocaleString()}`;
    }
    const converted = Math.round(half * rate);
    return new Intl.NumberFormat(undefined, {
      style: "currency",
      currency,
      maximumFractionDigits: 0,
    }).format(converted);
  };

  return { currency, rate, loaded, formatPrice, formatDownpayment };
}

import { Pool } from "pg";

// Use a global singleton to avoid exhausting connection pool on hot reloads
const globalForPg = globalThis as unknown as { pgPool: Pool | undefined };

export function getDb(): Pool {
  if (!globalForPg.pgPool) {
    let connectionString =
      process.env.DATABASE_URL ||
      "postgresql://postgres:postgres@localhost:5432/portfolio";

    const isLocal =
      connectionString.includes("localhost") ||
      connectionString.includes("127.0.0.1");

    connectionString = connectionString.replace(/sslmode=(prefer|require|verify-ca)/gi, "sslmode=verify-full");

    globalForPg.pgPool = new Pool({
      connectionString,
      max: 10,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 5000,
      ssl: isLocal ? false : { rejectUnauthorized: false },
    });
  }
  return globalForPg.pgPool;
}

export async function queryAll(sql: string, params: any[] = []) {
  const db = getDb();
  const res = await db.query(sql, params);
  return res.rows;
}

export async function queryOne(sql: string, params: any[] = []) {
  const db = getDb();
  const res = await db.query(sql, params);
  return res.rows[0] || null;
}

export async function execute(sql: string, params: any[] = []) {
  const db = getDb();
  return await db.query(sql, params);
}

import nodemailer from "nodemailer";
import { queryOne } from "@/lib/db";

export async function sendOtpEmail(toEmail: string, code: string, subject: string = "Your OTP Code") {
  const config = await queryOne("SELECT * FROM email_config WHERE id = 1") as any;
  if (!config || !config.smtp_host || !config.smtp_user || !config.smtp_password) {
    throw new Error("Email service is not configured by the administrator yet.");
  }

  const transporter = nodemailer.createTransport({
    host: config.smtp_host,
    port: Number(config.smtp_port) || 587,
    secure: Number(config.smtp_port) === 465,
    auth: { user: config.smtp_user, pass: config.smtp_password },
    tls: { rejectUnauthorized: false },
  });

  await transporter.sendMail({
    from: `"${config.sender_name || "Dee Jay"}" <${config.sender_email || "otp@deejay.dev"}>`,
    to: toEmail,
    subject,
    html: `
      <div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:24px;border:1px solid #e4e4e7;border-radius:16px;">
        <h2 style="font-size:20px;font-weight:bold;color:#18181b;margin-bottom:8px;">${subject}</h2>
        <p style="font-size:14px;color:#71717a;margin-bottom:24px;">Use the code below to proceed. It expires in 10 minutes.</p>
        <div style="background:#f4f4f5;border-radius:12px;padding:16px;text-align:center;margin-bottom:24px;">
          <span style="font-family:monospace;font-size:32px;font-weight:bold;letter-spacing:6px;color:#06b6d4;">${code}</span>
        </div>
        <p style="font-size:12px;color:#a1a1aa;border-top:1px solid #e4e4e7;padding-top:16px;">If you did not request this, please ignore this email.</p>
      </div>
    `,
  });
}

